insert into move_destinations (id, city, country, region, photo_label, image_url, match_scores, honest, stats, visa, sort_order, active) values ('lisbon', 'Lisbon', 'Portugal', 'Europe', 'Lisbon · Alfama rooftops at golden hour', 'https://images.unsplash.com/photo-1555881400-74d7aca32786?w=1200&q=80', '{"trip": 91, "nomad": 95, "move": 88}'::jsonb, '{"trip": "Easy to land in and walkable, but the hills and old trams mean slow crosstown trips. August is hot and tourist-packed.", "nomad": "A genuine nomad hub with great cafés and a big community — which means rents have climbed fast and the best flats go in days.", "move": "Sunny, safe and welcoming, with a clear residency path. Bureaucracy is slow and finding long-term housing takes patience."}'::jsonb, '{"trip": [["Business hotels", "From €120/nt"], ["Median wifi", "92 Mbps"], ["Airport → centre", "20 min metro"]], "nomad": [["Furnished 1-bed", "€1,100–1,600/mo"], ["Coworking spaces", "40+"], ["Nomad visa", "D8 eligible"]], "move": [["Cost · couple", "€2,300/mo"], ["Healthcare", "Public + strong private"], ["Intl schools", "12 in metro"]]}'::jsonb, '{"trip": {"headline": "Visa-free up to 90 days", "body": "Most US, UK, EU, CA & AU passports enter Schengen visa-free for 90 days in any 180-day window.", "tag": "Schengen · 90/180"}, "nomad": {"headline": "Digital Nomad Visa (D8)", "body": "For stays over 90 days. Show remote income of roughly €3,280/mo. Renewable, and counts toward residency.", "tag": "D8 · 12 months"}, "move": {"headline": "Residence permit (D7 / D8)", "body": "Apply from a long-stay visa, then a residence permit. Permanent residency possible after 5 years.", "tag": "Path to PR · 5 yrs"}}'::jsonb, 0, true) on conflict (id) do update set city=excluded.city, country=excluded.country, region=excluded.region, photo_label=excluded.photo_label, image_url=excluded.image_url, match_scores=excluded.match_scores, honest=excluded.honest, stats=excluded.stats, visa=excluded.visa, sort_order=excluded.sort_order, active=true, updated_at=now();
insert into move_destinations (id, city, country, region, photo_label, image_url, match_scores, honest, stats, visa, sort_order, active) values ('mexicocity', 'Mexico City', 'Mexico', 'Latin America', 'Mexico City · leafy Roma Norte streets', 'https://images.unsplash.com/photo-1518659526051-2ca369704b54?w=1200&q=80', '{"trip": 86, "nomad": 93, "move": 82}'::jsonb, '{"trip": "Huge, vibrant and great value, but the scale means long taxi rides and altitude can leave you breathless for a day or two.", "nomad": "Incredible food, culture and a fast-growing remote scene. Roma & Condesa are lovely but rents there now rival European cities.", "move": "Warm people and a low cost of living, but you''ll want functional Spanish and patience for paperwork to truly settle."}'::jsonb, '{"trip": [["Business hotels", "From $95/nt"], ["Median wifi", "70 Mbps"], ["Airport → centre", "35 min"]], "nomad": [["Furnished 1-bed", "$700–1,200/mo"], ["Coworking spaces", "60+"], ["Tourist entry", "Up to 180 days"]], "move": [["Cost · couple", "$1,700/mo"], ["Healthcare", "Excellent private"], ["Intl schools", "20+ in CDMX"]]}'::jsonb, '{"trip": {"headline": "Visa-free, up to 180 days", "body": "Many nationalities enter as a tourist for a stay set on arrival — commonly up to 180 days.", "tag": "Tourist · up to 180d"}, "nomad": {"headline": "Tourist entry covers it", "body": "No dedicated nomad visa, but the generous tourist entry comfortably covers a 1–3 month stint.", "tag": "No special visa"}, "move": {"headline": "Temporary Resident Visa", "body": "Apply at a consulate with proof of income or savings. Valid 1–4 years and leads to permanent residency.", "tag": "Path to PR · 4 yrs"}}'::jsonb, 1, true) on conflict (id) do update set city=excluded.city, country=excluded.country, region=excluded.region, photo_label=excluded.photo_label, image_url=excluded.image_url, match_scores=excluded.match_scores, honest=excluded.honest, stats=excluded.stats, visa=excluded.visa, sort_order=excluded.sort_order, active=true, updated_at=now();
insert into move_destinations (id, city, country, region, photo_label, image_url, match_scores, honest, stats, visa, sort_order, active) values ('bangkok', 'Bangkok', 'Thailand', 'Asia-Pacific', 'Bangkok · Chao Phraya river at dusk', 'https://images.unsplash.com/photo-1563492065-454364424952?w=1200&q=80', '{"trip": 84, "nomad": 90, "move": 79}'::jsonb, '{"trip": "Cheap, fast and endlessly convenient — but heat, humidity and traffic are real. Get a hotel near a BTS Skytrain stop.", "nomad": "Unbeatable value with modern condos and cafés everywhere. Air quality dips in the burning season (Feb–Apr).", "move": "Comfortable and affordable for years, though long-term visas need planning and property ownership rules are strict."}'::jsonb, '{"trip": [["Business hotels", "From $55/nt"], ["Median wifi", "120 Mbps"], ["Airport → centre", "30 min rail"]], "nomad": [["Furnished condo", "$450–900/mo"], ["Coworking spaces", "50+"], ["Nomad visa", "DTV eligible"]], "move": [["Cost · couple", "$1,500/mo"], ["Healthcare", "World-class private"], ["Intl schools", "30+ in city"]]}'::jsonb, '{"trip": {"headline": "Visa-exemption on arrival", "body": "Many passports get a 30–60 day visa-exempt stay on entry, extendable once at an immigration office.", "tag": "Exempt · 30–60d"}, "nomad": {"headline": "Destination Thailand Visa", "body": "The DTV allows 180 days per entry over a 5-year multi-entry validity — built for remote workers.", "tag": "DTV · 5-yr multi"}, "move": {"headline": "Long-Term Resident visa", "body": "The LTR visa offers up to 10 years for qualifying professionals, retirees and high earners.", "tag": "LTR · up to 10 yrs"}}'::jsonb, 2, true) on conflict (id) do update set city=excluded.city, country=excluded.country, region=excluded.region, photo_label=excluded.photo_label, image_url=excluded.image_url, match_scores=excluded.match_scores, honest=excluded.honest, stats=excluded.stats, visa=excluded.visa, sort_order=excluded.sort_order, active=true, updated_at=now();
insert into move_destinations (id, city, country, region, photo_label, image_url, match_scores, honest, stats, visa, sort_order, active) values ('tbilisi', 'Tbilisi', 'Georgia', 'Europe', 'Tbilisi · Old Town & sulphur baths', 'https://images.unsplash.com/photo-1565008576549-57569a49371d?w=1200&q=80', '{"trip": 78, "nomad": 88, "move": 80}'::jsonb, '{"trip": "Astonishing value and famously easy entry, but it''s smaller and quieter than the big hubs — charming, not buzzing.", "nomad": "One of the simplest places in the world to base yourself, with cheap flats and fast wifi. English is less common day-to-day.", "move": "Very low cost of living and light bureaucracy, though it''s further from family back home and winters are grey."}'::jsonb, '{"trip": [["Boutique hotels", "From $45/nt"], ["Median wifi", "65 Mbps"], ["Airport → centre", "25 min"]], "nomad": [["Furnished 1-bed", "$500–850/mo"], ["Coworking spaces", "15+"], ["Nomad program", "Remotely from Georgia"]], "move": [["Cost · couple", "$1,300/mo"], ["Healthcare", "Affordable private"], ["Intl schools", "6 in city"]]}'::jsonb, '{"trip": {"headline": "Visa-free up to 1 year", "body": "Around 95 nationalities can enter and stay visa-free for a full 365 days — one of the most generous policies anywhere.", "tag": "Visa-free · 365d"}, "nomad": {"headline": "Remotely from Georgia", "body": "A simple program for remote workers and freelancers to stay long-term, on top of the 1-year visa-free entry.", "tag": "Remote-work · 1 yr"}, "move": {"headline": "Residence permits", "body": "Work, study and investment residence permits are straightforward, with a path to permanent residency.", "tag": "Path to PR"}}'::jsonb, 3, true) on conflict (id) do update set city=excluded.city, country=excluded.country, region=excluded.region, photo_label=excluded.photo_label, image_url=excluded.image_url, match_scores=excluded.match_scores, honest=excluded.honest, stats=excluded.stats, visa=excluded.visa, sort_order=excluded.sort_order, active=true, updated_at=now();
insert into move_destinations (id, city, country, region, photo_label, image_url, match_scores, honest, stats, visa, sort_order, active) values ('berlin', 'Berlin', 'Germany', 'Europe', 'Berlin · Spree riverside & TV tower skyline', null, '{"trip": 85, "nomad": 89, "move": 84}'::jsonb, '{"trip": "Endlessly walkable with world-class museums and nightlife, but grey winters and patchy English at counters can catch first-timers off guard.", "nomad": "A huge, established freelancer scene with cheap-by-European-standards rent — though the famous bureaucracy (Anmeldung, Bürgeramt queues) tests everyone''s patience.", "move": "Affordable, green and tolerant, with strong tenant protections. Apartment hunting is genuinely competitive and German fluency unlocks far more."}'::jsonb, '{"trip": [["Business hotels", "From €95/nt"], ["Median wifi", "105 Mbps"], ["Airport → centre", "30 min train"]], "nomad": [["Furnished 1-bed", "€950–1,400/mo"], ["Coworking spaces", "70+"], ["Freelance visa", "Freiberufler eligible"]], "move": [["Cost · couple", "€2,100/mo"], ["Healthcare", "Public + private (Gesetzlich/Privat)"], ["Intl schools", "18 in metro"]]}'::jsonb, '{"trip": {"headline": "Visa-free up to 90 days", "body": "Most US, UK, CA & AU passports enter Schengen visa-free for 90 days in any 180-day window.", "tag": "Schengen · 90/180"}, "nomad": {"headline": "Freelance visa (Freiberufler)", "body": "Self-employed professionals can apply for a freelance residence permit with proof of clients and income.", "tag": "Freelance · 1–2 yrs"}, "move": {"headline": "Residence permit + Anmeldung", "body": "Register your address (Anmeldung) within 14 days, then apply for a residence permit. PR possible after 5 years.", "tag": "Path to PR · 5 yrs"}}'::jsonb, 4, true) on conflict (id) do update set city=excluded.city, country=excluded.country, region=excluded.region, photo_label=excluded.photo_label, image_url=excluded.image_url, match_scores=excluded.match_scores, honest=excluded.honest, stats=excluded.stats, visa=excluded.visa, sort_order=excluded.sort_order, active=true, updated_at=now();
insert into move_destinations (id, city, country, region, photo_label, image_url, match_scores, honest, stats, visa, sort_order, active) values ('buenosaires', 'Buenos Aires', 'Argentina', 'Latin America', 'Buenos Aires · Palermo Soho cafés and jacarandas', null, '{"trip": 80, "nomad": 87, "move": 77}'::jsonb, '{"trip": "Gorgeous European-style architecture and unbeatable steak, but inflation means prices shift fast and ATMs often run dry.", "nomad": "A buzzing café and coworking culture with some of the best value left in the Americas — though the peso''s swings make budgeting a moving target.", "move": "Warm, cultured and welcoming, with relatively easy residency, but the economy''s volatility affects everyday banking and savings."}'::jsonb, '{"trip": [["Business hotels", "From $60/nt"], ["Median wifi", "75 Mbps"], ["Airport → centre", "40 min"]], "nomad": [["Furnished 1-bed", "$450–800/mo"], ["Coworking spaces", "35+"], ["Digital nomad visa", "Available"]], "move": [["Cost · couple", "$1,100/mo"], ["Healthcare", "Good public + affordable private"], ["Intl schools", "15 in city"]]}'::jsonb, '{"trip": {"headline": "Visa-free up to 90 days", "body": "Most US, UK, EU, CA & AU passports enter visa-free for tourism for up to 90 days.", "tag": "Visa-free · 90d"}, "nomad": {"headline": "Digital Nomad Visa", "body": "A renewable visa for remote workers earning foreign income, valid up to 180 days per stay.", "tag": "Nomad visa · 180d"}, "move": {"headline": "Rentista / residency visa", "body": "Show steady passive or foreign income to qualify for temporary residency, renewable toward permanent status.", "tag": "Path to PR · 2 yrs"}}'::jsonb, 5, true) on conflict (id) do update set city=excluded.city, country=excluded.country, region=excluded.region, photo_label=excluded.photo_label, image_url=excluded.image_url, match_scores=excluded.match_scores, honest=excluded.honest, stats=excluded.stats, visa=excluded.visa, sort_order=excluded.sort_order, active=true, updated_at=now(