insert into move_destinations (id, city, country, region, photo_label, image_url, match_scores, honest, stats, visa, sort_order, active) values ('tokyo', 'Tokyo', 'Japan', 'Asia-Pacific', 'Tokyo · Shibuya crossing at night', null, '{"trip": 88, "nomad": 84, "move": 81}'::jsonb, '{"trip": "Immaculately run and endlessly fascinating, but it''s expensive by Asian standards and queues/etiquette norms take adjusting to.", "nomad": "Fast, reliable everything and a small but growing remote-work scene — though English is limited and short-term flexible leases are scarce.", "move": "Safe, efficient and high quality of life, but visa sponsorship usually needs a local employer and the language barrier is real for daily life."}'::jsonb, '{"trip": [["Business hotels", "From $90/nt"], ["Median wifi", "110 Mbps"], ["Airport → centre", "45 min train"]], "nomad": [["Furnished 1-bed", "$1,100–1,700/mo"], ["Coworking spaces", "45+"], ["Digital nomad visa", "6-month eligible"]], "move": [["Cost · couple", "$2,600/mo"], ["Healthcare", "Universal + excellent"], ["Intl schools", "25+ in metro"]]}'::jsonb, '{"trip": {"headline": "Visa-free up to 90 days", "body": "Most US, UK, EU, CA & AU passports enter visa-free for short tourism or business stays.", "tag": "Visa-free · 90d"}, "nomad": {"headline": "Digital Nomad Visa", "body": "A 6-month visa for remote workers with a minimum income threshold and private health insurance.", "tag": "Nomad visa · 6 mo"}, "move": {"headline": "Work or specialist visa", "body": "Usually needs employer sponsorship (e.g. Engineer/Specialist or Highly Skilled Professional). PR possible after years of residence.", "tag": "Sponsorship usual"}}'::jsonb, 6, true) on conflict (id) do update set city=excluded.city, country=excluded.country, region=excluded.region, photo_label=excluded.photo_label, image_url=excluded.image_url, match_scores=excluded.match_scores, honest=excluded.honest, stats=excluded.stats, visa=excluded.visa, sort_order=excluded.sort_order, active=