insert into move_destinations (id, city, country, region, photo_label, image_url, match_scores, honest, stats, visa, sort_order, active) values ('capetown', 'Cape Town', 'South Africa', 'Africa', 'Cape Town · Table Mountain over the Atlantic seaboard', null, '{"trip": 82, "nomad": 86, "move": 78}'::jsonb, '{"trip": "Spectacular scenery and great value, but loadshedding (power cuts) and safety awareness in certain areas need planning around.", "nomad": "A well-established nomad base with stunning surrounds and fast fibre internet — backup power and area choice matter more than elsewhere.", "move": "Affordable and beautiful, with a path to residency, though crime concerns and the rand''s volatility are real considerations to weigh."}'::jsonb, '{"trip": [["Business hotels", "From $65/nt"], ["Median wifi", "60 Mbps"], ["Airport → centre", "25 min"]], "nomad": [["Furnished 1-bed", "$600–1,000/mo"], ["Coworking spaces", "25+"], ["Remote work visa", "Available"]], "move": [["Cost · couple", "$1,400/mo"], ["Healthcare", "Strong private"], ["Intl schools", "10 in metro"]]}'::jsonb, '{"trip": {"headline": "Visa-free up to 90 days", "body": "Most US, UK, EU & CA passports enter visa-free for tourism for up to 90 days.", "tag": "Visa-free · 90d"}, "nomad": {"headline": "Remote Work Visa", "body": "A dedicated visa for remote workers earning above a foreign-income threshold, valid up to 3 years.", "tag": "Remote visa · 3 yrs"}, "move": {"headline": "Critical skills / residency visa", "body": "Skilled workers can apply via the critical skills list; financially independent applicants have a separate route to residency.", "tag": "Path to PR"}}'::jsonb, 7, true) on conflict (id) do update set city=excluded.city, country=excluded.country, region=excluded.region, photo_label=excluded.photo_label, image_url=excluded.image_url, match_scores=excluded.match_scores, honest=excluded.honest, stats=excluded.stats, visa=excluded.visa, sort_order=excluded.sort_order, active=true, updated_at=now();
insert into move_destinations (id, city, country, region, photo_label, image_url, match_scores, honest, stats, visa, sort_order, active) values ('dubai', 'Dubai', 'United Arab Emirates', 'Middle East', 'Dubai · Marina skyline at dusk', null, '{"trip": 87, "nomad": 85, "move": 80}'::jsonb, '{"trip": "Slick, safe and easy to navigate, but it''s pricier than people expect and the summer heat is genuinely brutal.", "nomad": "Tax-free income and a polished remote-work visa make this attractive — though it''s an expensive base with a car-dependent layout.", "move": "Modern infrastructure and zero income tax, but residency is employment/sponsorship-tied and the cultural and legal norms differ sharply from the West."}'::jsonb, '{"trip": [["Business hotels", "From $110/nt"], ["Median wifi", "95 Mbps"], ["Airport → centre", "20 min metro"]], "nomad": [["Furnished 1-bed", "$1,500–2,400/mo"], ["Coworking spaces", "30+"], ["Virtual work visa", "1-year eligible"]], "move": [["Cost · couple", "$3,200/mo"], ["Healthcare", "Mandatory private insurance"], ["Intl schools", "40+ in emirate"]]}'::jsonb, '{"trip": {"headline": "Visa on arrival, up to 90 days", "body": "Most US, UK, EU, CA & AU passports get a free visa on arrival for tourism, often extendable.", "tag": "Visa on arrival · 90d"}, "nomad": {"headline": "Virtual Working Programme", "body": "A 1-year remote-work visa for employees and freelancers earning above a minimum monthly income.", "tag": "Remote visa · 1 yr"}, "move": {"headline": "Employment or Golden Visa", "body": "Most residency is employer-sponsored; high earners, investors and specialists can qualify for a long-term Golden Visa.", "tag": "Sponsorship or Golden Visa"}}'::jsonb, 8, true) on conflict (id) do update set city=excluded.city, country=excluded.country, region=excluded.region, photo_label=excluded.photo_label, image_url=excluded.image_url, match_scores=excluded.match_scores, honest=excluded.honest, stats=excluded.stats, visa=excluded.visa, sort_order=excluded.sort_order, active=true, updated_at=now();
insert into move_destinations (id, city, country, region, photo_label, image_url, match_scores, honest, stats, visa, sort_order, active) values ('toronto', 'Toronto', 'Canada', 'North America', 'Toronto · CN Tower over the harbourfront', null, '{"trip": 83, "nomad": 81, "move": 86}'::jsonb, '{"trip": "Clean, friendly and easy to get around, but accommodation is pricier than most US cities and winters are long and cold.", "nomad": "Solid infrastructure and a real tech scene, but there''s no dedicated nomad visa and the cost of living rivals major US cities.", "move": "One of the easier Western countries to build a long-term path in, with strong public services — but housing costs and winters are a real adjustment."}'::jsonb, '{"trip": [["Business hotels", "From $130/nt"], ["Median wifi", "100 Mbps"], ["Airport → centre", "25 min train"]], "nomad": [["Furnished 1-bed", "$1,600–2,300/mo"], ["Coworking spaces", "50+"], ["Tourist entry", "Up to 6 months"]], "move": [["Cost · couple", "$3,000/mo"], ["Healthcare", "Universal (provincial)"], ["Intl schools", "N/A — strong public system"]]}'::jsonb, '{"trip": {"headline": "eTA or visa-free, up to 6 months", "body": "Visa-exempt nationals get an eTA on arrival by air; entry is typically granted for up to 6 months.", "tag": "eTA · 6 mo"}, "nomad": {"headline": "Tourist entry covers it", "body": "No dedicated nomad visa yet, but the standard 6-month tourist entry comfortably covers most nomad stints.", "tag": "No special visa"}, "move": {"headline": "Express Entry / PR pathways", "body": "Skilled-worker immigration via Express Entry or provincial nominee programs leads directly to permanent residency.", "tag": "Path to PR"}}'::jsonb, 9, true) on conflict (id) do update set city=excluded.city, country=excluded.country, region=excluded.region, photo_label=excluded.photo_label, image_url=excluded.image_url, match_scores=excluded.match_scores, honest=excluded.honest, stats=excluded.stats, visa=excluded.visa, sort_order=excluded.sort_order, active=true, updated_at=now();
insert into move_destinations (id, city, country, region, photo_label, image_url, match_scores, honest, stats, visa, sort_order, active) values ('sydney', 'Sydney', 'Australia', 'Oceania', 'Sydney · Opera House & harbour bridge', null, '{"trip": 84, "nomad": 79, "move": 83}'::jsonb, '{"trip": "Stunning beaches and an easy-going pace, but flights in are long and it''s one of the more expensive stops on this list.", "nomad": "Great weather and lifestyle, but the cost of living is high and there''s no nomad-specific visa — most rely on the working holiday route.", "move": "High quality of life and a clear skilled-migration pathway, though it''s a lengthy and competitive points-based process."}'::jsonb, '{"trip": [["Business hotels", "From $140/nt"], ["Median wifi", "85 Mbps"], ["Airport → centre", "20 min train"]], "nomad": [["Furnished 1-bed", "$1,700–2,400/mo"], ["Coworking spaces", "40+"], ["Working Holiday visa", "Ages 18–35"]], "move": [["Cost · couple", "$3,400/mo"], ["Healthcare", "Universal (Medicare)"], ["Intl schools", "N/A — strong public/private mix"]]}'::jsonb, '{"trip": {"headline": "eVisitor or ETA, up to 90 days", "body": "Most EU passports get a free eVisitor visa; US, CA & others get an ETA — both typically valid for 90-day stays.", "tag": "eVisitor/ETA · 90d"}, "nomad": {"headline": "Working Holiday visa", "body": "For eligible passports aged 18–35 (or 18–30), allowing up to 12 months of work and travel.", "tag": "WHV · 12 mo"}, "move": {"headline": "Skilled migration (points-tested)", "body": "A points-based system assessing age, skills and English ability; successful applicants get permanent residency directly.", "tag": "Points-tested PR"}}'::jsonb, 10, true) on conflict (id) do update set city=excluded.city, country=excluded.country, region=excluded.region, photo_label=excluded.photo_label, image_url=excluded.image_url, match_scores=excluded.match_scores, honest=excluded.honest, stats=excluded.stats, visa=excluded.visa, sort_order=excluded.sort_or