insert into move_destinations (id, city, country, region, photo_label, image_url, match_scores, honest, stats, visa, sort_order, active) values ('singapore', 'Singapore', 'Singapore', 'Asia-Pacific', 'Singapore · Marina Bay skyline at night', null, '{"trip": 86, "nomad": 82, "move": 79}'::jsonb, '{"trip": "Spotless, safe and effortless to navigate, but it''s genuinely one of the most expensive cities in the world to even pass through.", "nomad": "World-class infrastructure and connectivity, but the cost of living is brutal and there''s no real nomad visa — most stay on tourist entry.", "move": "Excellent healthcare, safety and schools, but residency is tightly controlled and almost always requires employer sponsorship."}'::jsonb, '{"trip": [["Business hotels", "From $150/nt"], ["Median wifi", "130 Mbps"], ["Airport → centre", "25 min train"]], "nomad": [["Furnished 1-bed", "$2,200–3,200/mo"], ["Coworking spaces", "60+"], ["Tourist entry", "Up to 90 days"]], "move": [["Cost · couple", "$4,200/mo"], ["Healthcare", "Excellent public + private"], ["Intl schools", "30+ in city-state"]]}'::jsonb, '{"trip": {"headline": "Visa-free up to 90 days", "body": "Most US, UK, EU, CA & AU passports enter visa-free for tourism for up to 90 days.", "tag": "Visa-free · 90d"}, "nomad": {"headline": "Tourist entry covers it", "body": "No dedicated nomad visa; most remote workers base here on the standard 90-day visa-free entry.", "tag": "No special visa"}, "move": {"headline": "Employment Pass", "body": "Skilled professionals need employer sponsorship for an Employment Pass; PR is discretionary and highly selective.", "tag": "Sponsorship usual"}}'::jsonb, 11, true) on conflict (id) do update set city=excluded.city, country=excluded.country, region=excluded.region, photo_label=excluded.photo_label, image_url=excluded.image_url, match_scores=excluded.match_scores, honest=excluded.honest, stats=excluded.stats, visa=excluded.visa, sort_order=excluded.sort_order, active=true, updated_at=now(